const $=id=>document.getElementById(id);let feed,line='',lastRefresh=new Date();const fmt=new Intl.DateTimeFormat('en-CA',{timeZone:'America/Toronto',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',second:'2-digit',hourCycle:'h23'});function now(){let p=Object.fromEntries(fmt.formatToParts(new Date()).map(x=>[x.type,x.value]));return {date:`${p.year}-${p.month}-${p.day}`,min:+p.hour*60 + +p.minute + +p.second/60,time:`${p.hour}:${p.minute}:${p.second}`}}function time(m){return `${String(Math.floor(m/60)%24).padStart(2,'0')}:${String(m%60).padStart(2,'0')}${m>=1440?' +1':''}`}function esc(v){return String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}function tick(){let n=now();$('clock').textContent=n.time;$('today').textContent=new Date().toLocaleDateString('en-CA',{timeZone:'America/Toronto',weekday:'short',month:'short',day:'numeric'}).toUpperCase()+' · ET'}tick();setInterval(tick,1000);
function render(){if(!feed)return;let n=now(),date=$('date').value,from=$('from').value,to=$('to').value;let key=date.replaceAll('-',''),dayOffset=date===n.date?0:1;let results=[];let available=feed.days[key];let ids=(available||[]).map(id=>[id,0]);if(date===n.date){let d=new Date(date+'T12:00:00Z');d.setUTCDate(d.getUTCDate()-1);let prev=d.toISOString().slice(0,10).replaceAll('-','');ids.push(...(feed.days[prev]||[]).map(id=>[id,-1440]))}
for(let [id,offset] of ids){let p=feed.patterns[id];if(line&&p[0]!==line)continue;let i=p[2].findIndex(s=>s[0]===from&&s[3]!=='1');if(i<0)continue;let j=to?p[2].findIndex((s,k)=>k>i&&s[0]===to&&s[4]!=='1'):p[2].length-1;if(j<=i)continue;let departure=p[2][i][2]+offset;if(date===n.date&&departure<n.min)continue;if(offset<0&&departure<0)continue;results.push({p,i,j,departure,arrival:p[2][j][1]+offset})}results.sort((a,b)=>a.departure-b.departure);$('code').textContent=from;$('station').textContent=feed.stops[from].name;$('subtitle').textContent='Train departures · '+(to?'To '+feed.stops[to].name:'All destinations');$('count').textContent=results.length+' scheduled departure'+(results.length===1?'':'s')+(date===n.date?' remaining today':' on '+date);$('coverage').textContent=`Schedule imported ${feed.imported}. Feed coverage: ${Object.keys(feed.days).sort()[0]}–${Object.keys(feed.days).sort().at(-1)}. Automatic feed refresh runs daily when the included GitHub workflow is enabled.`;
if(!results.length){$('rows').innerHTML=`<div class="empty"><h3>${!available?'Schedule unavailable':from===to?'Choose different stations':'No direct trains found'}</h3><p>${!available?'This date is outside the downloaded feed. Choose a date within the feed coverage.':from===to?'Your start and end station must be different.':'Try another line, destination, or travel date. Only direct trains with remaining departures are shown.'}</p></div>`;return}
$('rows').innerHTML=results.slice(0,100).map(({p,i,j,departure,arrival})=>{let l=feed.lines[p[0]],mins=Math.ceil(departure-n.min),count=date===n.date?(mins<1?'Due':mins<60?mins+' min':Math.floor(mins/60)+'h '+mins%60+'m'):'Scheduled';return `<details class="train"><summary class="train-main"><span class="depart">${time(departure)}</span><span class="destination"><span class="badge" style="background:${esc(l.color)}">${esc(p[0])}</span><span><div class="dest-name">${esc(p[1])}</div><div class="line-name">${esc(l.name)} · Train ${esc(p[3])}${to?' · stops at '+esc(feed.stops[to].name):''}</div></span></span><span class="arrival">${time(arrival)}<small>${to?'At destination':'Final stop'}</small></span><span class="countdown">${count}</span><span class="chevron">⌄</span></summary><div class="stops">${p[2].slice(i,j+1).map(s=>`<span class="stop"><b>${esc(feed.stops[s[0]].name)}</b>${time(s[1])}</span>`).join('')}</div></details>`}).join('');}
fetch('feed.json', {cache:'no-store'}).then(r=>{if(!r.ok)throw Error('Feed unavailable');return r.json()}).then(d=>{feed=d;let q=new URLSearchParams(location.search);$('from').value=d.stops[q.get('from')]?q.get('from'):'UN';$('to').value=d.stops[q.get('to')]?q.get('to'):'';$('date').value=/^\d{4}-\d{2}-\d{2}$/.test(q.get('date')||'')?q.get('date'):now().date;$('lines').innerHTML='<button class="selected" data-line="">All lines</button>'+Object.entries(d.lines).sort().map(([id,l])=>`<button data-line="${esc(id)}"><i style="background:${esc(l.color)}"></i>${esc(l.name)}</button>`).join('');setupStationSearch();syncStationSearch();render()}).catch(e=>{$('rows').innerHTML='<div class="empty"><h3>Unable to load the schedule</h3><p>Check your connection and refresh the page.</p></div>';$('count').textContent='Schedule unavailable';console.error(e)});
function update(){syncStationSearch();let q=new URLSearchParams({from:$('from').value,to:$('to').value,date:$('date').value});history.replaceState(null,'','?'+q);render()}['from','to','date'].forEach(id=>$(id).addEventListener('change',update));$('lines').addEventListener('click',e=>{let b=e.target.closest('button');if(!b)return;line=b.dataset.line;document.querySelectorAll('#lines button').forEach(x=>x.classList.toggle('selected',x===b));render()});$('swap').onclick=()=>{if(!$('to').value)return;let a=$('from').value;$('from').value=$('to').value;$('to').value=a;update()};$('reset').onclick=()=>{$('from').value='UN';$('to').value='';$('date').value=now().date;line='';document.querySelectorAll('#lines button').forEach(x=>x.classList.toggle('selected',x.dataset.line===''));update()};$('refresh').onclick=()=>{render();$('updated').textContent='Board refreshed '+now().time};$('fullscreen').onclick=()=>{if(document.fullscreenElement)document.exitFullscreen();else document.documentElement.requestFullscreen().catch(()=>{})};setInterval(()=>{if(!document.querySelector('.train[open]'))render()},30000);

function syncStationSearch(){if(!feed)return;for(const id of ['from','to'])$(id+'-search').value=feed.stops[$(id).value]?.name||(id==='to'?'All destinations':'');}
function setupStationSearch(){
 const stations=Object.entries(feed.stops).sort((a,b)=>a[1].name.localeCompare(b[1].name)).map(([id,s])=>({id,name:s.name}));
 for(const id of ['from','to']){
  const input=$(id+'-search'),list=$(id+'-options');let matches=[],active=-1;
  input.disabled=false;
  function close(){list.hidden=true;input.setAttribute('aria-expanded','false');input.removeAttribute('aria-activedescendant');active=-1;}
  function paint(){list.innerHTML=matches.length?matches.map((s,i)=>`<span role="option" id="${id}-option-${i}" data-index="${i}" aria-selected="${i===active}" class="station-option">${esc(s.name)}</span>`).join(''):'<span class="station-no-results">No matching stations</span>';if(active>=0){input.setAttribute('aria-activedescendant',`${id}-option-${active}`);$(id+'-option-'+active).scrollIntoView({block:'nearest'});}else input.removeAttribute('aria-activedescendant');}
  function show(all=false){const query=all?'':input.value.trim().toLowerCase();const choices=id==='to'?[{id:'',name:'All destinations'},...stations]:stations;matches=choices.filter(s=>s.name.toLowerCase().includes(query)||s.id.toLowerCase()===query);active=-1;list.hidden=false;input.setAttribute('aria-expanded','true');paint();}
  function choose(index){if(!matches[index])return;$(id).value=matches[index].id;close();update();input.blur();}
  input.addEventListener('focus',()=>{input.select();show(true);});
  input.addEventListener('input',()=>show());
  input.addEventListener('keydown',e=>{if(e.key==='Escape'){close();syncStationSearch();return;}if(e.key==='ArrowDown'||e.key==='ArrowUp'){e.preventDefault();if(list.hidden)show(true);if(matches.length){active=(active+(e.key==='ArrowDown'?1:-1)+matches.length)%matches.length;paint();}}if(e.key==='Enter'){e.preventDefault();choose(active<0?0:active);}});
  list.addEventListener('pointerdown',e=>e.preventDefault());
  list.addEventListener('click',e=>{let option=e.target.closest('[data-index]');if(option)choose(+option.dataset.index);});
  input.addEventListener('blur',()=>{close();syncStationSearch();});
 }
}
